package com.shiphappens.logistics.exception;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import org.slf4j.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.resource.NoResourceFoundException; import java.time.Instant;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class); record Error(Instant timestamp,int status,String error,String message,String path,String requestId){} private ResponseEntity<Error> response(HttpStatus s,String code,String message,HttpServletRequest r){return ResponseEntity.status(s).body(new Error(Instant.now(),s.value(),code,message,r.getRequestURI(),(String)r.getAttribute("requestId")));}
 @ExceptionHandler(ApiException.class) ResponseEntity<Error> api(ApiException e,HttpServletRequest r){return response(e.status(),e.code(),e.getMessage(),r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> validation(MethodArgumentNotValidException e,HttpServletRequest r){String message=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+" "+x.getDefaultMessage()).orElse("Request validation failed");return response(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",message,r);} @ExceptionHandler(ConstraintViolationException.class) ResponseEntity<Error> constraint(ConstraintViolationException e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",e.getMessage(),r);} @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Error> integrity(DataIntegrityViolationException e,HttpServletRequest r){return response(HttpStatus.CONFLICT,"CONSTRAINT_VIOLATION","The request conflicts with an existing record.",r);} @ExceptionHandler(NoResourceFoundException.class) ResponseEntity<Error> notFound(NoResourceFoundException e,HttpServletRequest r){return response(HttpStatus.NOT_FOUND,"NOT_FOUND","The requested resource was not found.",r);} @ExceptionHandler(Exception.class) ResponseEntity<Error> unknown(Exception e,HttpServletRequest r){log.error("Unexpected application error",e);return response(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_SERVER_ERROR","An unexpected error occurred.",r);} }